INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 10, 101, '2023-01-01', 1, 500);

-- Buyer 102: Buys IPHONE, no S8
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (2, 11, 102, '2023-01-02', 1, 800);

-- Buyer 103: Buys both S8 and IPHONE
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 12, 103, '2023-01-03', 1, 500);
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (2, 12, 103, '2023-01-04', 1, 800);

-- Buyer 104: Buys S8 multiple times, no IPHONE
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 13, 104, '2023-01-05', 1, 500);
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 13, 104, '2023-01-06', 2, 1000);

