-- This row will be ignored by Q1's INNER JOIN. In Q2's CTE, PRODUCT_NAME will be NULL for this row.
-- However, conditions like PRODUCT_NAME = 'S8' or PRODUCT_NAME = 'IPHONE' will evaluate to UNKNOWN for NULL PRODUCT_NAME, 
-- so this buyer will not be included in the S8 or IPHONE buyer sets based on this sale.
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (NULL, 14, 105, '2023-01-07', 1, 100);

