schema:
CREATE TABLE PRODUCT (
    PRODUCT_KEY INT,
    PRIMARY KEY (PRODUCT_KEY)
);
CREATE TABLE CUSTOMER (
    CUSTOMER_ID INT,
    PRODUCT_KEY INT,
    PRIMARY KEY (CUSTOMER_ID),
    FOREIGN KEY (PRODUCT_KEY) REFERENCES PRODUCT(PRODUCT_KEY)
);

counterexample:
-- Due to the `PRIMARY KEY (PRODUCT_KEY)` constraint on the `PRODUCT` table, it is impossible to create a dataset where `COUNT(DISTINCT PRODUCT_KEY)` and `COUNT(PRODUCT_KEY)` from the `PRODUCT` table yield different results. Consequently, Q1 and Q2 are logically equivalent under the given schema, and a counterexample where they produce different results cannot be generated without violating schema constraints.
-- The following INSERT statements represent a valid database under the given schema, but for which Q1 and Q2 will always produce identical results.

INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (2);

INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (101, 1);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (102, 2);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (103, NULL);

-- For this data:
-- Q1 subquery: (SELECT COUNT(DISTINCT PRODUCT_KEY) FROM PRODUCT) -> 2
-- Q2 subquery: (SELECT COUNT(PRODUCT_KEY) FROM PRODUCT) -> 2

-- For customer 101: COUNT(DISTINCT CUSTOMER.PRODUCT_KEY) -> 1. (1 = 2) is FALSE.
-- For customer 102: COUNT(DISTINCT CUSTOMER.PRODUCT_KEY) -> 1. (1 = 2) is FALSE.
-- For customer 103: COUNT(DISTINCT CUSTOMER.PRODUCT_KEY) -> 0. (0 = 2) is FALSE.

-- Both Q1 and Q2 will return an empty set, thus producing identical results.

